package org.dromara.property.charge.receivable.service;
import org.dromara.common.core.exception.ServiceException; import org.dromara.property.charge.payment.mapper.*; import org.dromara.property.charge.receivable.domain.Receivable; import org.dromara.property.charge.receivable.mapper.ReceivableMapper; import org.dromara.property.scope.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import static org.junit.jupiter.api.Assertions.assertThrows; import static org.mockito.Mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class ReceivablePaymentHistoryServiceTest {
 @Mock ReceivableMapper receivableMapper; @Mock PaymentAllocationMapper allocationMapper; @Mock PaymentMapper paymentMapper; @Mock PropertyProjectScopeService scope;
 @Test void historyUsesPersistedReceivableProjectForIdorCheck(){Receivable r=new Receivable();r.setId(1L);r.setProjectId(99L);when(receivableMapper.selectById(1L)).thenReturn(r);doThrow(new ServiceException("deny")).when(scope).assertBusinessAccess(99L,PropertyBusinessDomain.FINANCE,ProjectBusinessAction.READ);ReceivablePaymentHistoryService service=new ReceivablePaymentHistoryService(receivableMapper,allocationMapper,paymentMapper,scope);assertThrows(ServiceException.class,()->service.query(1L));verifyNoInteractions(allocationMapper,paymentMapper);}
}
